const items = $input.all();
const rawInput = items[0]?.json?.body || items[0]?.json || {};
const headers = items[0]?.json?.headers || {};

// 1. Recursive call prevention
if (headers['x-researchpilot-orchestrated'] === 'true' || headers['x-researchpilot-orchestrated'] === true) {
  throw new Error('Validation Error: Recursive orchestration detected. Request rejected to prevent loops.');
}

// 2. Validate topic
if (rawInput.topic === undefined || rawInput.topic === null) {
  throw new Error('Validation Error: Missing required field "topic".');
}
if (typeof rawInput.topic !== 'string') {
  throw new Error('Validation Error: "topic" must be a string.');
}
const topic = rawInput.topic.trim();
if (topic.length < 3 || topic.length > 250) {
  throw new Error('Validation Error: "topic" length must be between 3 and 250 characters.');
}

// 3. Validate country & language
let country = 'in';
if (rawInput.country !== undefined && rawInput.country !== null) {
  if (typeof rawInput.country !== 'string') throw new Error('Validation Error: "country" must be an ISO code string.');
  const cleanCountry = rawInput.country.trim().toLowerCase();
  if (!/^[a-z]{2}$/.test(cleanCountry)) throw new Error('Validation Error: "country" must be a valid 2-letter ISO code.');
  country = cleanCountry;
}

let language = 'en';
if (rawInput.language !== undefined && rawInput.language !== null) {
  if (typeof rawInput.language !== 'string') throw new Error('Validation Error: "language" must be an ISO code string.');
  const cleanLanguage = rawInput.language.trim().toLowerCase();
  if (!/^[a-z]{2}(-[a-z]{2})?$/.test(cleanLanguage)) throw new Error('Validation Error: "language" must be a valid ISO language code.');
  language = cleanLanguage;
}

// 4. Validate engines
const validEngineSet = new Set(['google', 'google_scholar', 'google_news', 'google_patents']);
let selectedEngines = ['google', 'google_scholar', 'google_news', 'google_patents'];
if (Array.isArray(rawInput.engines)) {
  if (rawInput.engines.length === 0) {
    throw new Error('Validation Error: "engines" array must not be empty.');
  }
  const filtered = [];
  const seen = new Set();
  for (const e of rawInput.engines) {
    if (typeof e === 'string') {
      const norm = e.trim().toLowerCase();
      if (validEngineSet.has(norm) && !seen.has(norm)) {
        seen.add(norm);
        filtered.push(norm);
      }
    }
  }
  if (filtered.length === 0) {
    throw new Error('Validation Error: No valid engines specified. Supported: google, google_scholar, google_news, google_patents.');
  }
  selectedEngines = filtered;
}

// 5. Source Limits & Depth
let maxSources = 20;
if (rawInput.maxSources !== undefined && rawInput.maxSources !== null) {
  const num = Number(rawInput.maxSources);
  if (!isNaN(num) && num >= 1 && num <= 100) {
    maxSources = Math.floor(num);
  }
}

let researchDepth = 'deep';
if (typeof rawInput.researchDepth === 'string') {
  const d = rawInput.researchDepth.trim().toLowerCase();
  if (['fast', 'standard', 'deep', 'search_only'].includes(d)) {
    researchDepth = d;
  }
}

const includeDocuments = rawInput.includeDocuments !== false;
const confidenceThreshold = typeof rawInput.confidenceThreshold === 'number' ? rawInput.confidenceThreshold : 0.75;
const documents = Array.isArray(rawInput.documents) ? rawInput.documents : null;

// 6. Generate Request ID
const requestId = 'req_' + Date.now().toString(36) + '_' + Math.random().toString(36).substring(2, 9);

// 7. Route to Downstream Phase
let primaryEndpoint = 'researchpilot-phase5';
if (researchDepth === 'fast' || researchDepth === 'search_only') {
  primaryEndpoint = 'researchpilot-phase2';
} else if (researchDepth === 'standard') {
  primaryEndpoint = includeDocuments ? 'researchpilot-phase4' : 'researchpilot-phase3';
}

const primaryPayload = {
  topic,
  country,
  language,
  engines: selectedEngines
};

if (primaryEndpoint === 'researchpilot-phase5') {
  primaryPayload.confidenceThreshold = confidenceThreshold;
  if (documents) primaryPayload.documents = documents;
} else if (primaryEndpoint === 'researchpilot-phase4') {
  if (documents) primaryPayload.documents = documents;
}

const fallbackPayload = {
  topic,
  country,
  language,
  engines: selectedEngines
};

return [{
  json: {
    requestId,
    topic,
    country,
    language,
    selectedEngines,
    maxSources,
    researchDepth,
    includeDocuments,
    confidenceThreshold,
    primaryEndpoint,
    primaryPayload,
    fallbackPayload,
    startedAt: Date.now()
  }
}];

const item = $input.first()?.json || {};
const ctx = $('Validate Request & Build Context').first()?.json || {};

const topic = ctx.topic || 'Unknown Topic';
const requestId = ctx.requestId || 'req_unknown';
const maxSources = ctx.maxSources || 20;
const selectedEngines = ctx.selectedEngines || ['google'];
const researchDepth = ctx.researchDepth || 'deep';
const startedAt = ctx.startedAt || Date.now();

const isSuccess = item && (item.success === true || Array.isArray(item.sources));
const status = isSuccess ? 'completed' : 'partial';

let rawSources = [];
if (Array.isArray(item?.externalIntelligence?.sources)) {
  rawSources = item.externalIntelligence.sources;
} else if (Array.isArray(item?.sources)) {
  rawSources = item.sources;
}

let docChunks = [];
if (Array.isArray(item?.documentIntelligence?.retrievedChunks)) {
  docChunks = item.documentIntelligence.retrievedChunks;
}

const seenUrls = new Set();
const boundedSources = [];
for (const s of rawSources) {
  const key = s.url || s.sourceId;
  if (!seenUrls.has(key)) {
    seenUrls.add(key);
    boundedSources.push(s);
    if (boundedSources.length >= maxSources) break;
  }
}

let executiveSummary = '';
let keyFindings = [];
let contradictions = [];
let researchGaps = [];
let limitations = [];
let claimCredibilityLedger = undefined;
let agenticReflection = undefined;

if (item?.executiveSummary) {
  executiveSummary = item.executiveSummary;
} else if (item?.summary?.executiveSummary) {
  executiveSummary = item.summary.executiveSummary;
} else {
  executiveSummary = 'Research synthesis for "' + topic + '" synthesized across ' + selectedEngines.join(', ') + '.';
}

if (Array.isArray(item?.claimCredibilityLedger)) {
  claimCredibilityLedger = item.claimCredibilityLedger;
  keyFindings = claimCredibilityLedger.map(c => c.claimText + (Array.isArray(c.citedSources) && c.citedSources.length > 0 ? (' [' + c.citedSources.join(', ') + ']') : ''));
} else if (Array.isArray(item?.summary?.keyFindings)) {
  keyFindings = item.summary.keyFindings;
} else {
  keyFindings = boundedSources.slice(0, 5).map(s => s.title + ': ' + (s.snippet || 'No snippet available') + ' [' + s.sourceId + ']');
}

if (Array.isArray(item?.contradictionMatrix)) {
  contradictions = item.contradictionMatrix;
} else if (Array.isArray(item?.summary?.alignmentsAndContradictions)) {
  contradictions = item.summary.alignmentsAndContradictions;
}

if (Array.isArray(item?.summary?.researchGaps)) {
  researchGaps = item.summary.researchGaps;
} else if (Array.isArray(item?.agenticReflection?.actionableInsights)) {
  researchGaps = item.agenticReflection.actionableInsights;
}

if (Array.isArray(item?.summary?.limitations)) {
  limitations = item.summary.limitations;
} else {
  limitations = ['Findings grounded on multi-engine SerpApi search snippets and language model inference horizon.'];
}

if (item?.agenticReflection) {
  agenticReflection = item.agenticReflection;
}

const validSourceMap = new Set([
  ...boundedSources.map(s => s.sourceId),
  ...rawSources.map(s => s.sourceId),
  ...docChunks.map(c => c.documentSourceId)
]);

const reportBlob = JSON.stringify({ executiveSummary, keyFindings, contradictions });
const sMatches = reportBlob.match(/\bS\d{3}\b/g) || [];
const dMatches = reportBlob.match(/\bD\d{3}\b/g) || [];
const allCitations = [...sMatches, ...dMatches];
const uniqueFoundCitations = Array.from(new Set(allCitations));

const validCitations = [];
const invalidCitationIds = [];

for (const cid of uniqueFoundCitations) {
  if (validSourceMap.has(cid)) {
    validCitations.push(cid);
  } else {
    invalidCitationIds.push(cid);
  }
}

let unsupportedClaimCount = 0;
if (Array.isArray(claimCredibilityLedger)) {
  for (const c of claimCredibilityLedger) {
    const cited = c.citedSources || [];
    const hasInvalid = cited.some(id => !validSourceMap.has(id));
    if (hasInvalid) unsupportedClaimCount++;
  }
}

const citationValidation = {
  valid: invalidCitationIds.length === 0,
  invalidCitationIds,
  unsupportedClaimCount,
  totalCitations: allCitations.length,
  uniqueSourcesCited: validCitations.length,
  groundingIntegrity: invalidCitationIds.length === 0 ? '100% Grounded' : 'Partially Grounded'
};

return [{
  json: {
    success: true,
    requestId,
    topic,
    status,
    report: {
      executiveSummary,
      keyFindings,
      contradictions,
      researchGaps,
      limitations,
      claimCredibilityLedger,
      agenticReflection
    },
    sources: boundedSources,
    metadata: {
      enginesUsed: selectedEngines,
      sourceCount: boundedSources.length,
      maxSourcesConfigured: maxSources,
      researchDepth,
      confidenceIndex: item?.confidenceIndex || null,
      citationValidation,
      orchestration: {
        primaryPhase: ctx.primaryEndpoint,
        executedPhase: ctx.primaryEndpoint,
        fallbackEngaged: false,
        executionTimeMs: Date.now() - startedAt
      }
    },
    errors: []
  }
}];

const item = $input.first()?.json || {};
const ctx = $('Validate Request & Build Context').first()?.json || {};

const topic = ctx.topic || 'Unknown Topic';
const requestId = ctx.requestId || 'req_unknown';
const maxSources = ctx.maxSources || 20;
const selectedEngines = ctx.selectedEngines || ['google'];
const researchDepth = ctx.researchDepth || 'deep';
const startedAt = ctx.startedAt || Date.now();

let rawSources = [];
if (Array.isArray(item?.sources)) {
  rawSources = item.sources;
}

const seenUrls = new Set();
const boundedSources = [];
for (const s of rawSources) {
  const key = s.url || s.sourceId;
  if (!seenUrls.has(key)) {
    seenUrls.add(key);
    boundedSources.push(s);
    if (boundedSources.length >= maxSources) break;
  }
}

const executiveSummary = boundedSources.length > 0
  ? 'Fallback multi-engine evidence retrieved for "' + topic + '". Downstream intelligence agent experienced an upstream timeout or interruption; returning verified raw multi-engine search sources.'
  : 'Search services returned no results for "' + topic + '". Please try broader terms or select different engines.';

const keyFindings = boundedSources.slice(0, 5).map(s => s.title + ': ' + (s.snippet || 'No snippet available') + ' [' + s.sourceId + ']');

const citationValidation = {  valid: true,
  invalidCitationIds: [],
  unsupportedClaimCount: 0,
  totalCitations: keyFindings.length,
  uniqueSourcesCited: boundedSources.slice(0, 5).length,
  groundingIntegrity: '100% Grounded'
};

return [{
  json: {
    success: boundedSources.length > 0,
    requestId,
    topic,
    status: boundedSources.length > 0 ? 'partial' : 'failed',
    report: {
      executiveSummary,
      keyFindings,
      contradictions: [],
      researchGaps: ['Deep AI synthesis uncompleted due to downstream phase fallback.'],
      limitations: ['Raw search results only; advanced LLM reflection omitted.']
    },
    sources: boundedSources,
    metadata: {
      enginesUsed: selectedEngines,
      sourceCount: boundedSources.length,
      maxSourcesConfigured: maxSources,
      researchDepth,
      confidenceIndex: {
        score: boundedSources.length > 0 ? 0.65 : 0.0,
        rating: boundedSources.length > 0 ? 'PARTIAL EVIDENCE (RAW SEARCH)' : 'NO EVIDENCE FOUND',
        status: 'FALLBACK_ENGAGED'
      },
      citationValidation,
      orchestration: {
        primaryPhase: ctx.primaryEndpoint,
        executedPhase: 'researchpilot-phase2 (fallback)',
        fallbackEngaged: true,
        executionTimeMs: Date.now() - startedAt
      }
    },
    errors: [
      'Primary phase (' + ctx.primaryEndpoint + ') failed or timed out. Graceful fallback to Phase 2 multi-engine search was automatically engaged.'
    ]
  }
}];

const raw = $input.first()?.json || {};
const errorMsg = typeof raw.error === 'string'
  ? raw.error
  : (raw.error?.message || raw.message || 'Validation Error: Invalid input parameters.');
const cleanMsg = errorMsg.replace(/\s*\[line\s+\d+\]$/, '').replace(/^Error:\s*/, '');

return [{
  json: {
    success: false,
    requestId: 'req_rejected',
    status: 'failed',
    error: {
      code: 'INVALID_INPUT',
      message: cleanMsg,
      details: 'Topic must be a non-empty string between 3 and 250 characters. Country and language must be valid ISO codes. Supported engines: google, google_scholar, google_news, google_patents.'
    },
    limitations: [
      'Request rejected at orchestrator boundary before downstream phase invocation.'
    ]
  }
}];
